      "O uso do hífen mudou bastante com o Acordo Ortográfico, e é justamente essa mudança que a banca gosta de explorar — muita gente ainda usa a regra antiga sem perceber. A regra central hoje depende da letra final do prefixo e da letra inicial da palavra seguinte.",
      "Com prefixos terminados em vogal (como 'auto', 'anti', 'infra'), usa-se hífen se a palavra seguinte começar com a mesma vogal, com 'h', ou com 'r'/'s' (dobrando a consoante quando não há hífen): 'auto-observação', 'anti-higiênico', mas 'autoestrada' (sem hífen, vogais diferentes).",
      "Com prefixos terminados em consoante (como 'super', 'inter', 'hiper'), usa-se hífen se a palavra seguinte começar com a mesma consoante ou com 'h': 'super-revista' não existe, mas 'inter-racial', 'hiper-requintado'. Sem hífen nos demais casos: 'supermercado', 'internacional'."
