    "corpo": [
      "'Onde' indica lugar fixo, sem ideia de movimento, e é usado com verbos que não pedem a preposição 'a' (estar, ficar, morar): 'A delegacia onde ele trabalha'. 'Aonde' indica movimento, deslocamento, e é usado com verbos de movimento que pedem a preposição 'a' (ir, chegar): 'Aonde você vai?'.",
      "'Senão' (junto) equivale a 'caso contrário' ou 'a não ser': 'Estude, senão vai reprovar'. 'Se não' (separado) é a conjunção condicional 'se' seguida do advérbio de negação 'não': 'Se não estudar, vai reprovar' — repare que dá para inverter e testar: 'Se você não estudar...'.",
      "'Afim' (junto) é adjetivo que significa 'semelhante, relacionado': 'Temas afins'. 'A fim de' (separado) é locução que indica finalidade, propósito: 'Estudei bastante a fim de passar na prova'."
    ],
    "pontosChave": [
      "Onde = lugar fixo (sem movimento); Aonde = lugar com movimento (verbos como ir, chegar).",
      "Senão = caso contrário/a não ser; Se não = 'se' + 'não', testável invertendo a ordem.",
      "Afim = semelhante/relacionado (adjetivo); A fim de = com o propósito de (finalidade)."
    ],
