    "corpo": [
      "Substantivo nomeia seres, objetos, sentimentos e ideias — é a classe de palavra que pode receber artigo antes. Adjetivo qualifica ou caracteriza o substantivo, concordando em gênero e número com ele: 'policiais competentes'. Artigo indica se o substantivo é conhecido (definido: o, a, os, as) ou não (indefinido: um, uma, uns, umas).",
      "Casos especiais de plural de substantivos compostos merecem atenção: quando os dois elementos são variáveis (substantivo + substantivo, ou substantivo + adjetivo), ambos vão para o plural: 'guardas-noturnos'. Quando há uma preposição no meio, só o primeiro elemento varia: 'pães de mel' já no singular... mas 'pé de moleque' → 'pés de moleque'.",
      "Adjetivos compostos seguem regra própria: normalmente só o último elemento varia em gênero e número, e o primeiro fica invariável: 'blusas verde-escuras' (mas 'escuras' varia, 'verde' não)."
    ],
    "pontosChave": [
      "Substantivo nomeia, adjetivo qualifica (concordando em gênero/número), artigo define ou indefine.",
      "Plural de substantivo composto: ambos variáveis → ambos no plural; com preposição → só o primeiro varia.",
      "Adjetivo composto: geralmente só o último elemento varia (ex.: 'verde-escuras')."
    ],
