    "title": "Pronomes relativos e colocação pronominal",
    "assunto": "Morfologia e sintaxe",
    "tecnica": "Identificação de antecedente e ambiente de próclise/ênclise",
    "competencia": "Empregar pronomes relativos e aplicar corretamente próclise, mesóclise e ênclise",
