    "corpo": [
      "Os três modos verbais indicam a atitude do falante diante do fato: indicativo (fato certo, real — 'ele investigou'), subjuntivo (fato hipotético, incerto, desejo — 'se ele investigasse'), imperativo (ordem, pedido — 'investigue!'). Textos institucionais e boletins usam quase sempre o indicativo, por relatar fatos ocorridos.",
      "Voz ativa: o sujeito pratica a ação ('O policial deteve o suspeito'). Voz passiva: o sujeito sofre a ação, podendo ser analítica (com verbo auxiliar + particípio: 'O suspeito foi detido pelo policial') ou sintética/pronominal (com o pronome 'se': 'Detiveram-se dois suspeitos' / 'Prendeu-se o suspeito').",
      "Um erro comum é confundir voz passiva sintética com sujeito indeterminado — na passiva sintética, o 'se' é partícula apassivadora e o verbo concorda com o sujeito paciente ('Vendem-se casas' = casas são vendidas, concordância no plural); no sujeito indeterminado, o verbo fica sempre na 3ª pessoa do singular ('Precisa-se de policiais')."
    ],
    "pontosChave": [
      "Indicativo = fato certo; Subjuntivo = hipótese/desejo; Imperativo = ordem/pedido.",
      "Voz ativa: sujeito pratica a ação; Voz passiva: sujeito sofre a ação (analítica com 'ser + particípio', sintética com 'se').",
      "Na passiva sintética, o verbo concorda com o sujeito paciente; no indeterminado, fica sempre no singular."
    ],
